css:
:root { --p04-col: 56rem; --p04-area-min: 6.5rem; --p04-room: 1.75rem; --p04-tab-end: 1.5rem; }
.p04-wrap { max-width: var(--p04-col); margin-inline: auto; display: grid; gap: var(--s-4); margin-top: calc(var(--p04-scroll, 0rem) * -1); }
.p04-top { display: grid; gap: var(--s-2); }
.p04-list { display: grid; gap: var(--s-5); }
.p04-sec { display: grid; gap: var(--s-2); }
.p04-field { display: grid; gap: var(--s-3); padding: var(--s-3); }
.p04-text { max-width: var(--measure); overflow-wrap: anywhere; cursor: pointer; }
.p04-comments { display: grid; margin-inline-start: var(--s-3); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p04-comments { margin-inline-start: 50%; } }
.rec.p04-comment { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "body actions"; padding-inline: 0; border-top: var(--w1) solid var(--rule); }
.p04-more { padding-top: var(--s-1); }
.p04-dis .link-btn[aria-disabled="true"] { color: var(--c-disabled-text); text-decoration: none; cursor: not-allowed; }
.p04-more .tip { display: block; margin-bottom: var(--s-1); }
.p04-tools { display: flex; justify-content: center; gap: var(--s-2); }
.p04-add { display: flex; justify-content: center; }
.p04-addwrap { position: relative; display: inline-block; }
.p04-tip { position: absolute; left: 50%; top: calc(100% + var(--s-1)); translate: -50% 0; white-space: nowrap; z-index: 5; }
.p04-cform { display: grid; gap: var(--s-2); padding-block: var(--s-2) var(--s-1); border-top: var(--w1) solid var(--rule); }
.p04-area { position: relative; }
.p04-area .textarea { min-height: var(--p04-area-min); resize: none; }
.field__count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.p04-btns { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.p04-btns .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p04-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p04-e { --frame-w: var(--w2); }
.dialog__foot.p04-foot { flex-direction: column; }
.p04-foot > * { flex: none; }
.p04-off .ibtn--framed[aria-disabled="true"] { border-color: var(--c-disabled-border); }
.p04-app .tabwrap > .tab { padding-inline: var(--s-1) var(--p04-tab-end); }
.p04-app .tab__help { inset-inline-end: var(--w2); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p04-wrap.p04-shift { margin-top: calc(var(--p04-shift, 0rem) * -1); } }
